/*
 * Manual standalone driver for the snmp_parse_args_fuzzer target.
 * Reads one input file (or stdin) and feeds it to LLVMFuzzerTestOneInput,
 * matching the OSS-Fuzz snmp_parse_args_fuzzer semantics without libFuzzer.
 */
#include <net-snmp/net-snmp-config.h>
#include <net-snmp/net-snmp-includes.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);
int LLVMFuzzerInitialize(int *argc, char ***argv);

int main(int argc, char **argv)
{
    const char *path = NULL;
    FILE *fp;
    long sz;
    uint8_t *buf;
    size_t n;

    if (argc > 1)
        path = argv[1];

    if (path) {
        fp = fopen(path, "rb");
        if (!fp)
            return 0;
    } else {
        fp = stdin;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        if (path)
            fclose(fp);
        return 0;
    }
    sz = ftell(fp);
    if (sz < 0) {
        if (path)
            fclose(fp);
        return 0;
    }
    fseek(fp, 0, SEEK_SET);

    buf = malloc(sz ? (size_t)sz : 1);
    if (!buf) {
        if (path)
            fclose(fp);
        return 0;
    }
    n = fread(buf, 1, (size_t)sz, fp);
    if (path)
        fclose(fp);

    LLVMFuzzerTestOneInput(buf, n);
    free(buf);
    return 0;
}

/*
 * Manual standalone driver for the snmp_parse_args_fuzzer target.
 * Reads one input file (argv[1]) or all of stdin and feeds it to
 * LLVMFuzzerTestOneInput, matching the OSS-Fuzz snmp_parse_args_fuzzer
 * semantics without libFuzzer.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

int main(int argc, char **argv)
{
    FILE *fp = stdin;
    uint8_t *buf;
    size_t cap = 65536, n = 0;
    int c;

    if (argc > 1) {
        fp = fopen(argv[1], "rb");
        if (!fp)
            return 0;
    }

    buf = malloc(cap);
    if (!buf) {
        if (fp != stdin)
            fclose(fp);
        return 0;
    }

    /* read all bytes until EOF, growing the buffer as needed */
    while ((c = fgetc(fp)) != EOF) {
        if (n == cap) {
            uint8_t *nbuf = realloc(buf, cap * 2);
            if (!nbuf) {
                free(buf);
                if (fp != stdin)
                    fclose(fp);
                return 0;
            }
            buf = nbuf;
            cap *= 2;
        }
        buf[n++] = (uint8_t)c;
    }
    if (fp != stdin)
        fclose(fp);

    LLVMFuzzerTestOneInput(buf, n);
    free(buf);
    return 0;
}

