{
    FILE *fp = stdin;
    uint8_t *buf;
    size_t cap = 65536, n = 0;
    int c;
    int i;

    fprintf(stderr, "DRIVER argc=%d", argc);
    for (i = 0; i < argc; i++)
        fprintf(stderr, " argv[%d]=[%s]", i, argv[i]);
    fprintf(stderr, "\n");

    if (argc > 1) {
        fp = fopen(argv[1], "rb");
        fprintf(stderr, "DRIVER fopen(%s)=%s\n", argv[1], fp ? "ok" : "FAIL");
        if (!fp)
